package vitor.tinelli.barcos;

public class Barco {
    private String nome;
    private int tamanho;

    public Barco(String nome, int tamanho) {
        this.nome = nome;
        this.tamanho = tamanho;
    }

    public String getNome() {
        return nome;
    }

    public void setNome(String nome) {
        this.nome = nome;
    }

    public int getTamanho() {
        return tamanho;
    }

    public void setTamanho(int tamanho) {
        this.tamanho = tamanho;
    }
}

package vitor.tinelli.barcos;

import java.util.ArrayList;
import java.util.List;

public class BasePorto {
    protected String nome;
    protected List<Barco> barcosAtracados;

    public BasePorto(String nome) {
        this.nome = nome;
        this.barcosAtracados = new ArrayList<>();
    }

    public boolean atracarBarco(Barco barco) {
        barcosAtracados.add(barco);
        return true;
    }

    public boolean desatracarBarco(Barco barco) {
        return barcosAtracados.remove(barco);
    }

    public String getNome() {
        return nome;
    }

    public List<Barco> getBarcosAtracados() {
        return barcosAtracados;
    }
}

package vitor.tinelli.barcos;

import java.util.ArrayList;
import java.util.List;

public class MainBarcos {
    public static void main(String[] args) {
        // Criando a lista de 5 barcos com diferentes tamanhos
        List<Barco> barcos = new ArrayList<>();
        barcos.add(new Barco("Barco 1", 2));
        barcos.add(new Barco("Barco 2", 5));
        barcos.add(new Barco("Barco 3", 7));
        barcos.add(new Barco("Barco 4", 12));
        barcos.add(new Barco("Barco 5", 20));

        // Criando os dois portos
        PortoPequeno portoPequeno = new PortoPequeno("Porto Pequeno");
        PortoGrande portoGrande = new PortoGrande("Porto Grande");

        // Percorrendo a lista de barcos e tentando atracar
        for (Barco barco : barcos) {
            // Tenta atracar primeiro no porto pequeno
            if (portoPequeno.atracarBarco(barco)) {
                System.out.println(barco.getNome() + " atracado no porto pequeno");
            } else if (portoGrande.atracarBarco(barco)) {
                System.out.println(barco.getNome() + " atracado no porto grande");
            } else {
                System.out.println(barco.getNome() + " não pôde ser atracado em nenhum porto");
            }
        }
    }
}

package vitor.tinelli.barcos;

public class PortoGrande extends BasePorto {

    public PortoGrande(String nome) {
        super(nome);
    }

    @Override
    public boolean atracarBarco(Barco barco) {
        if (barco.getTamanho() >= 10) {
            return super.atracarBarco(barco);
        }
        return false;
    }
}

package vitor.tinelli.barcos;

public class PortoPequeno extends BasePorto {

    public PortoPequeno(String nome) {
        super(nome);
    }

    @Override
    public boolean atracarBarco(Barco barco) {
        if (barco.getTamanho() <= 10) {
            return super.atracarBarco(barco);
        }
        return false;
    }
}

public class MusicCloud {
    private List<Musica> musicasDisponiveis;

    public MusicCloud() {
        this.musicasDisponiveis = new ArrayList<>();
        inicializarMusicas();
    }

    private void inicializarMusicas() {
        musicasDisponiveis.add(new Musica("Hino do Real Paulista", "Real Paulista FC"));
        musicasDisponiveis.add(new Musica("Macarena", "Los Del Rio"));
        musicasDisponiveis.add(new Musica("Evidências", "Chitãozinho & Xororó"));
        musicasDisponiveis.add(new Musica("Bohemian Rhapsody", "Queen"));
        musicasDisponiveis.add(new Musica("Imagine", "John Lennon"));
        musicasDisponiveis.add(new Musica("Hotel California", "Eagles"));
        musicasDisponiveis.add(new Musica("Stairway to Heaven", "Led Zeppelin"));
    }

    public Musica pesquisarMusica(String titulo) throws MusicaNaoEncontradaException {
        for (Musica musica : musicasDisponiveis) {
            if (musica.getTitulo().equalsIgnoreCase(titulo)) {
                return musica;
            }
        }
        throw new MusicaNaoEncontradaException("A música " + titulo + " não foi encontrada no sistema.");
    }

    public List<Musica> getMusicasDisponiveis() {
        return musicasDisponiveis;
    }
}
